<?php
namespace Tests\Feature;
use App\Enums\UserRole;use App\Models\Customer;use App\Models\Supplier;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class NextStaffDirectoryApiTest extends TestCase{use RefreshDatabase;
public function test_owner_can_create_and_list_suppliers():void{$owner=User::factory()->create(['role'=>UserRole::Owner]);Sanctum::actingAs($owner,['staff:suppliers']);$this->postJson('/api/v1/staff/suppliers',['name'=>'Supplier Next','contact_name'=>'Kontak','phone'=>'08123','email'=>'supplier@example.test','is_active'=>true])->assertCreated();$this->getJson('/api/v1/staff/suppliers?q=Supplier')->assertOk()->assertJsonPath('data.suppliers.0.name','Supplier Next')->assertJsonPath('data.suppliers.0.products_count',0);$this->assertDatabaseHas('activity_logs',['action'=>'supplier.created']);}
public function test_cashier_can_create_and_search_customers():void{$cashier=User::factory()->create(['role'=>UserRole::Cashier]);Sanctum::actingAs($cashier,['staff:customers']);$this->postJson('/api/v1/staff/customers',['name'=>'Pelanggan Next','phone'=>'081234567890','email'=>'customer@example.test','type'=>'umkm','address'=>'Alamat uji'])->assertCreated();$this->getJson('/api/v1/staff/customers?q=081234')->assertOk()->assertJsonPath('data.customers.0.name','Pelanggan Next')->assertJsonPath('data.customers.0.sales_count',0)->assertJsonPath('data.customers.0.orders_count',0);$this->assertDatabaseHas('activity_logs',['action'=>'customer.created']);}
public function test_directory_access_respects_role_and_abilities():void{$cashier=User::factory()->create(['role'=>UserRole::Cashier]);Sanctum::actingAs($cashier,['staff:suppliers']);$this->getJson('/api/v1/staff/suppliers')->assertForbidden();$owner=User::factory()->create(['role'=>UserRole::Owner]);Sanctum::actingAs($owner,['staff:dashboard']);$this->getJson('/api/v1/staff/customers')->assertForbidden();$customer=User::factory()->create(['role'=>UserRole::Customer]);Sanctum::actingAs($customer,['staff:customers']);$this->getJson('/api/v1/staff/customers')->assertForbidden();}
}